# Generated by build.py from recipe.yml for recipe surl-run-a-fixture-from-a-config-file. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from the test environment`n")
[IO.File]::WriteAllText((Join-Path $PWD 'test-env.conf'), "# The test environment, checked in beside the tests: surl -K test-env.conf`n# The passwords are for throwaway test accounts only.`n`ndirectory = site`nuser = `"tester:secret`"              # logs in over HTTP and FTP`nmail-domain = example.com`nmailbox = `"app@example.com:secret`"  # the app's mailbox, over SMTP`n`nallow-plaintext-auth                # the tests log in over plain http:// and ftp://`nallow-uploads                       # and upload over FTP`n`nurl = http://127.0.0.1:0/`nurl = ftp://127.0.0.1:0/`nurl = smtp://127.0.0.1:0/`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check-env.sh'), "#!/bin/sh`n# Starts the servers test-env.conf describes, waits for them, and tries each one once.`n# Any arguments are more surl options, read after the file, so they override it.`nset -e`nout=`$(mktemp)`nsurl -K test-env.conf `"`$@`" > `"`$out`" &`npid=`$!`ntrap 'kill `$pid 2>/dev/null || true; rm -f `"`$out`"' EXIT`n`n# One Listening on line per listen URL once all have bound; if surl exits first, stop with its code.`nuntil [ `"`$(grep -c '^Listening on ' `"`$out`")`" -eq 3 ]; do`n  kill -0 `$pid 2>/dev/null || { wait `$pid; exit `$?; }`n  sleep 0.1`ndone`nlistening() { sed -n `"s|^Listening on \(`$1://.*\)\`$|\1|p`" `"`$out`"; }`n`ncurl -fsS -u tester:secret `"`$(listening http)hello.txt`"`necho `"uploaded over FTP`" | curl -sS -u tester:secret -T - `"`$(listening ftp)upload.txt`"`ncurl -fsS -u tester:secret `"`$(listening http)upload.txt`"`nprintf 'Subject: Ready\r\n\r\nThe environment is up.\r\n' |`n  curl -sS -u app@example.com:secret --mail-from app@example.com --mail-rcpt app@example.com \`n    -T - `"`$(listening smtp)example.com`"`necho `"mail accepted`"`n")
sh check-env.sh
